		);

		const updateMountNode = this.getUpdateMountNode(anchor);

		const destroyOldBlock = deindent`
			@transitionManager.groupOutros();
			${name}.o(function() {
				${if_blocks}[ ${previous_block_index} ].d(1);
				${if_blocks}[ ${previous_block_index} ] = null;
			});
