						${name}.p(changed, ctx);
					} else {
						${name} = ${branch.block}(#component, ctx);
						${name}.c();
						${name}.m(${updateMountNode}, ${anchor});
					}
				`
			: branch.hasIntroMethod
				? deindent`
					if (!${name}) {
						${name} = ${branch.block}(#component, ctx);
						${name}.c();
					}
					${name}.i(${updateMountNode}, ${anchor});
				`
				: deindent`
					if (!${name}) {
						${name} = ${branch.block}(#component, ctx);
						${name}.c();
