		const anchorNode = parentNode ? 'null' : 'anchor';
		block.builders.mount.addLine(
			`${if_name}${name}.${mountOrIntro}(${initialMountNode}, ${anchorNode});`
		);

		const updateMountNode = this.getUpdateMountNode(anchor);

		const changeBlock = deindent`
			${hasElse
				? deindent`
					${name}.d(1);
				`
				: deindent`
					if (${name}) {
