			: `if (~${current_block_type_index}) `;

		block.addVariable(current_block_type_index);
		block.addVariable(name);

		block.builders.init.addBlock(deindent`
			var ${if_block_creators} = [
				${branches.map(branch => branch.block).join(',\n')}
			];

			var ${if_blocks} = [];

